package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"
	"sync"
	"time"
)

type KerberosTicket struct {
	ClientPrincipal string `json:"client_principal"`
	ServicePrincipal string `json:"service_principal"`
	DelegationFlag  bool   `json:"ok_as_delegate"`
	Forwardable     bool   `json:"forwardable"`
	Expiry          int64  `json:"expiry"`
	SessionKey      string `json:"session_key"`
}

type DelegationContext struct {
	OriginalClient  string
	IntermediateService string
	TargetService   string
	ConstrainedTo   []string
	EvidenceTicket  *KerberosTicket
}

type AuditEntry struct {
	Timestamp   time.Time `json:"timestamp"`
	Action      string    `json:"action"`
	Principal   string    `json:"principal"`
	Target      string    `json:"target"`
	Result      string    `json:"result"`
	Delegated   bool      `json:"delegated"`
}

var (
	auditLog     []AuditEntry
	auditMu      sync.Mutex
	serviceKey   = []byte("kdc-shared-secret-for-service-validation")
	allowedDelegationTargets = map[string][]string{
		"HTTP/frontend.corp.local": {"HTTP/backend-api.corp.local", "HTTP/database-proxy.corp.local"},
		"HTTP/backend-api.corp.local": {"HTTP/database-proxy.corp.local"},
	}
)

func writeAudit(action, principal, target, result string, delegated bool) {
	auditMu.Lock()
	defer auditMu.Unlock()
	auditLog = append(auditLog, AuditEntry{
		Timestamp: time.Now(),
		Action:    action,
		Principal: principal,
		Target:    target,
		Result:    result,
		Delegated: delegated,
	})
}

func validateTicketMAC(ticket *KerberosTicket, providedMAC string) bool {
	data := fmt.Sprintf("%s|%s|%v|%v|%d",
		ticket.ClientPrincipal,
		ticket.ServicePrincipal,
		ticket.DelegationFlag,
		ticket.Forwardable,
		ticket.Expiry)
	mac := hmac.New(sha256.New, serviceKey)
	mac.Write([]byte(data))
	expected := base64.StdEncoding.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(providedMAC))
}

func checkConstrainedDelegation(ctx context.Context, delCtx *DelegationContext) (bool, error) {
	allowedTargets, exists := allowedDelegationTargets[delCtx.IntermediateService]
	if !exists {
		return false, fmt.Errorf("service %s not configured for delegation", delCtx.IntermediateService)
	}

	targetAllowed := false
	for _, allowed := range allowedTargets {
		if strings.EqualFold(allowed, delCtx.TargetService) {
			targetAllowed = true
			break
		}
	}

	if !targetAllowed {
		return false, fmt.Errorf("delegation to %s not permitted", delCtx.TargetService)
	}

	if delCtx.EvidenceTicket == nil {
		return false, fmt.Errorf("no evidence ticket provided")
	}

	if time.Now().Unix() > delCtx.EvidenceTicket.Expiry {
		return false, fmt.Errorf("evidence ticket expired")
	}

	return true, nil
}

func performS4U2Proxy(delCtx *DelegationContext) (*KerberosTicket, error) {
	allowed, err := checkConstrainedDelegation(context.Background(), delCtx)
	if !allowed {
		writeAudit("S4U2Proxy", delCtx.OriginalClient, delCtx.TargetService, "DENIED: "+err.Error(), true)
		return nil, err
	}

	newTicket := &KerberosTicket{
		ClientPrincipal:  delCtx.OriginalClient,
		ServicePrincipal: delCtx.TargetService,
		DelegationFlag:   false,
		Forwardable:      false,
		Expiry:           time.Now().Add(10 * time.Minute).Unix(),
		SessionKey:       base64.StdEncoding.EncodeToString([]byte("delegated-session")),
	}

	writeAudit("S4U2Proxy", delCtx.OriginalClient, delCtx.TargetService, "GRANTED", true)
	return newTicket, nil
}

func performS4U2Self(servicePrincipal, targetUser string) (*KerberosTicket, error) {
	ticket := &KerberosTicket{
		ClientPrincipal:  targetUser,
		ServicePrincipal: servicePrincipal,
		DelegationFlag:   true,
		Forwardable:      true,
		Expiry:           time.Now().Add(10 * time.Minute).Unix(),
		SessionKey:       base64.StdEncoding.EncodeToString([]byte("s4u2self-session")),
	}

	writeAudit("S4U2Self", servicePrincipal, targetUser, "GRANTED", true)
	return ticket, nil
}

func delegationHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		CallerService   string `json:"caller_service"`
		TargetService   string `json:"target_service"`
		OnBehalfOf      string `json:"on_behalf_of"`
		EvidenceTicket  string `json:"evidence_ticket"`
		TicketMAC       string `json:"ticket_mac"`
		UseS4U2Self     bool   `json:"use_s4u2self"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request", http.StatusBadRequest)
		return
	}

	var evidenceTicket *KerberosTicket

	if req.UseS4U2Self {
		var err error
		evidenceTicket, err = performS4U2Self(req.CallerService, req.OnBehalfOf)
		if err != nil {
			http.Error(w, "S4U2Self failed", http.StatusForbidden)
			return
		}
	} else {
		if req.EvidenceTicket == "" {
			http.Error(w, "Evidence ticket required", http.StatusBadRequest)
			return
		}

		tickBytes, err := base64.StdEncoding.DecodeString(req.EvidenceTicket)
		if err != nil {
			http.Error(w, "Invalid ticket encoding", http.StatusBadRequest)
			return
		}

		evidenceTicket = &KerberosTicket{}
		if err := json.Unmarshal(tickBytes, evidenceTicket); err != nil {
			http.Error(w, "Invalid ticket format", http.StatusBadRequest)
			return
		}

		if !validateTicketMAC(evidenceTicket, req.TicketMAC) {
			writeAudit("TicketValidation", req.CallerService, req.TargetService, "DENIED: invalid MAC", true)
			http.Error(w, "Ticket validation failed", http.StatusForbidden)
			return
		}
	}

	delCtx := &DelegationContext{
		OriginalClient:      req.OnBehalfOf,
		IntermediateService: req.CallerService,
		TargetService:       req.TargetService,
		EvidenceTicket:      evidenceTicket,
	}

	resultTicket, err := performS4U2Proxy(delCtx)
	if err != nil {
		http.Error(w, err.Error(), http.StatusForbidden)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resultTicket)
}

func auditHandler(w http.ResponseWriter, r *http.Request) {
	auditMu.Lock()
	defer auditMu.Unlock()
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(auditLog)
}

func main() {
	http.HandleFunc("/delegate", delegationHandler)
	http.HandleFunc("/audit", auditHandler)
	log.Println("Kerberos delegation service starting on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
